def sort_array(array):
    return (
        []
        if len(array) == 0
        else sorted(array, reverse=(array[0] + array[-1]) % 2 == 0)
    )


# Unit test for function sort_array
def test_sort_array():
    assert sort_array([]) == []
    assert sort_array([3, 1, 5, 2, 1]) == [5, 3, 2, 1, 1]  # 3 + 1 is even
    assert sort_array([3, 5, 1, 2]) == [1, 2, 3, 5]         # 3 + 2 is odd
    assert sort_array([4]) == [4]
    assert sort_array([-2, 3, 0, 4]) == [4, 3, 0, -2]      # -2 + 4 is even
```
